SELECT , , , , ,
FROM course_enrollments course_enrollment JOIN gc_subject course ON course.id = course_enrollment.course_id JOIN gc_user u ON u.id = course_enrollment.user_id JOIN gc_user_info user_info ON user_info.id = u.info_id LEFT JOIN sys_file user_avatar_file ON user_info.avatar_file_id = user_avatar_file.id LEFT JOIN courses_progress course_progress ON course_enrollment.id = course_progress.enrollment_id WHERE course_enrollment.course_id = #{courseId} AND course_enrollment.user_id = #{userId}
AND course_enrollment.start_date >= #{startDate}
AND course_enrollment.end_date <= #{endDate}

SELECT , , , , ,
FROM course_enrollments course_enrollment JOIN gc_subject course ON course_enrollment.course_id = course.id AND course.master_id = #{masterId} JOIN gc_user u ON u.id = course_enrollment.user_id JOIN gc_user_info user_info ON user_info.id = u.info_id LEFT JOIN sys_file user_avatar_file ON user_info.avatar_file_id = user_avatar_file.id LEFT JOIN courses_progress course_progress ON course_enrollment.id = course_progress.enrollment_id WHERE 1=1
AND course_enrollment.start_date >= #{startDate}
AND course_enrollment.end_date <= #{endDate}

SELECT , , , , ,
FROM course_enrollments course_enrollment JOIN gc_subject course ON course_enrollment.course_id = course.id AND course.master_id = #{masterId} JOIN gc_user u ON u.id = course_enrollment.user_id JOIN gc_user_info user_info ON user_info.id = u.info_id LEFT JOIN sys_file user_avatar_file ON user_info.avatar_file_id = user_avatar_file.id LEFT JOIN courses_progress course_progress ON course_enrollment.id = course_progress.enrollment_id WHERE course_enrollment.user_id = #{userId}
